# ---------------------------------------------------------------------------
# RN-11 — `agreed_total_cents` es inmutable tras la creación del servicio.
#
# AC-01 exige que modificarlo falle "tanto por API como por SQL directo", así
# que la protección no puede vivir solo en la capa de aplicación. El trigger
# lleva cláusula WHEN para no ejecutar plpgsql en los UPDATE ordinarios, que son
# la inmensa mayoría (cambios de estado del servicio).
#
# `IS DISTINCT FROM` y no `<>`: el total acordado puede ser NULL (RN-15, pago
# único sin total declarado) y `NULL <> NULL` no es verdadero, así que con `<>`
# se podría escribir un total sobre un servicio que nació sin él.
# ---------------------------------------------------------------------------

_TRIGGER_FUNCTION = "service_reject_agreed_total_change"
_TRIGGER_NAME = "service_agreed_total_immutable"


def _create_agreed_total_immutability_trigger() -> None:
    op.execute(
        f"""
        CREATE FUNCTION {_TRIGGER_FUNCTION}() RETURNS trigger
        LANGUAGE plpgsql AS $$
        BEGIN
            RAISE EXCEPTION
                'RN-11: agreed_total_cents es inmutable (service.id=%, % -> %)',
                OLD.id, OLD.agreed_total_cents, NEW.agreed_total_cents
                USING ERRCODE = '23514';
        END;
        $$;
        """
    )
    op.execute(
        f"""
        CREATE TRIGGER {_TRIGGER_NAME}
            BEFORE UPDATE ON service
            FOR EACH ROW
            WHEN (NEW.agreed_total_cents IS DISTINCT FROM OLD.agreed_total_cents)
            EXECUTE FUNCTION {_TRIGGER_FUNCTION}();
        """
    )


